def solve():
	n = int(input())
	cards = []
	cnt = {}
	for i in range(n):
		card = tuple(map(int, input().split(' ')))
		cards.append(card)
		cnt[card[0]] = [0, 0]
		cnt[card[1]] = [0, 0]
	for card in cards:
		if card[0] != card[1]:
			cnt[card[0]][0] += 1
			cnt[card[1]][1] += 1
		else:
			cnt[card[0]][0] += 1
	border = (len(cards) + 1) // 2
	best = float('inf')
	for num in cnt.keys():
		count = cnt[num]
		if sum(count) >= border:
			needTop = max(0, border - count[0])
			best = min(best, needTop)
	if best == float('inf'):
		print(-1)
	else:
		print(best)
solve()
